197	            GroupedInventory.FirstOrDefault(gi => gi.Item == item) : 
198	            GroupedInventory.FirstOrDefault(gi => gi.Item.ItemTypeId == item.ItemTypeId);
199	        if(removeItem != null){
200	            if(removeItem.Quantity == 1)
201	            {
202	                GroupedInventory.Remove(removeItem);
203	            }
204	            else
205	            {
