226	    {
227	        foreach(ItemQuantity item in items)
228	        {
229	            if(Inventory.Count(i => i.ItemTypeId == item.ItemID) < item.Quantity)
230	            {
231	                return false;
232	            }
233	        }
234	
235	        return true;
236	    }
