namespace WPFUI.Factories;

using System.Data.Common;
using System.Linq;
using System.Windows.Automation;
using WPFUI.Models;
using WPFUI.Actions;

public static class ItemFactory
{   
    private static readonly List<GameItem> _standardGameItems = new List<GameItem>();

    static ItemFactory()
    {
        BuildWeapon(1001, "Pointy Stick", 1, 1, 2);
        BuildWeapon(1002, "Rusty Sword", 5, 1, 3);

        BuildWeapon(1501, "Snake Fangs", 0, 0, 2);
        BuildWeapon(1502, "Rat Claws", 0, 0, 2);
        BuildWeapon(1503, "Spider Fangs", 0, 0, 2);

        BuildHealingItem(2001, "Granola bar", 5, 2);

        BuildMiscellaneousItem(9001, "Snake fang", 1);
        BuildMiscellaneousItem(9002, "Snakeskin", 2);
        BuildMiscellaneousItem(9003, "Rat tail", 1);
        BuildMiscellaneousItem(9004, "Rat fur", 2);
        BuildMiscellaneousItem(9005, "Spider fang", 1);
        BuildMiscellaneousItem(9006, "Spider silk", 2);

        BuildMiscellaneousItem(3001, "Oats", 3);
        BuildMiscellaneousItem(3002, "Honey", 3);
        BuildMiscellaneousItem(3003, "Raisins", 3);
    }

    public static GameItem CreateGameItem(int itemTypeId)
    {   
        return _standardGameItems.FirstOrDefault(item => item.ItemTypeId ==  itemTypeId)?.Clone();

    }

    private static void BuildWeapon(int id, string name, int price, int minimumDamage, int maximumDamage)
    {
        GameItem weapon = new GameItem(GameItem.ItemCategory.Weapon, id, name, price, true);
        weapon.Action = new AttackWithWeapon(weapon, minimumDamage, maximumDamage);
        _standardGameItems.Add(weapon);

    }

    private static void BuildMiscellaneousItem(int id, string name, int price)
    {
        _standardGameItems.Add(new GameItem(GameItem.ItemCategory.Miscellanous, id,name, price));
    }

    private static void BuildHealingItem(int id, string name, int price, int hitPointsToHeal)
    {
        GameItem heal = new GameItem(GameItem.ItemCategory.Consumable, id, name, price);
        heal.Action = new Heal(heal, hitPointsToHeal);
        _standardGameItems.Add(heal);

    }

    public static string ItemName(int id)
    {
        return _standardGameItems.FirstOrDefault(i => i.ItemTypeId == id)?.Name ?? "";
    }
}

