using Microsoft.VisualStudio.TestTools.UnitTesting;
using WPFUI.Factories;
using WPFUI.Models;

namespace TestEngine.Probe
{
    [TestClass]
    public class TempProbe
    {
        [TestMethod]
        public void ProbeCombatDealsDamage()
        {
            Player p = new Player("P", "Fighter", 10, 10, 0, 0);
            p.AddItemToInventory(ItemFactory.CreateGameItem(1001));
            p.CurrentWeapon = p.Weapons[0];

            Monster m = MonsterFactory.GetMonster(1);
            int before = m.CurrentHitPoints;

            for (int i = 0; i < 50; i++)
            {
                p.UseCurrentWeaponOn(m);
            }

            Assert.AreNotEqual(before, m.CurrentHitPoints,
                $"monster HP unchanged after 50 attacks (still {m.CurrentHitPoints})");
        }

        [TestMethod]
        public void ProbeMaxHitPointsArgumentIsHonoured()
        {
            // 250 xp => level 3
            Player p = new Player("P", "Fighter", 100, 100, 250, 0);
            Assert.AreEqual(100, p.MaximumHitPoints,
                $"ctor was given health:100 but MaximumHitPoints is {p.MaximumHitPoints}");
        }

        [TestMethod]
        public void ProbeDuplicateActionMessages()
        {
            int messages = 0;
            Monster a = MonsterFactory.GetMonster(1);
            Monster b = MonsterFactory.GetMonster(1);
            a.OnActionPerformed += (s, e) => messages++;

            Player target = new Player("T", "F", 10, 10, 0, 0);
            b.UseCurrentWeaponOn(target);

            Assert.AreEqual(0, messages,
                $"monster A reported {messages} message(s) for an attack made by monster B");
        }
    }
}

