using WPFUI.Models;

namespace WPFUI.Actions;

public class Heal : BaseAction, IAction
{
    private readonly int _hitPointsToHeal;

    public Heal(GameItem itemInUse, int hitPointsHeal) : base(itemInUse)
    {
        if(itemInUse.Category != GameItem.ItemCategory.Consumable)
        {
            throw new ArgumentException($"{itemInUse.Name} is not a heal item");
        }
        _hitPointsToHeal = hitPointsHeal;
    }

    public IAction Clone(GameItem newItemInUse)
    {
        return new Heal(newItemInUse, _hitPointsToHeal);
    }

    public void Execute(LivingEntity actor, LivingEntity target)
    {
        string actorName = actor.Name.ToUpper();
        string targetName = target.Name.ToLower();
        ReportResult($"{actorName} heal {targetName} for {_hitPointsToHeal} point{(_hitPointsToHeal > 1 ? "s" : "")}.");
        target.Heal(_hitPointsToHeal);
    }
}

