using System.Collections.ObjectModel;

namespace WPFUI.Models;

public abstract class LivingEntity : BaseNotificationClass
{
    private string _name = string.Empty;
    private int _currentHitPoints;
    private int _maximumHitPoints;
    private int _gold;
    private int _level;
    private GameItem? _currentWeapon;
    private GameItem? _currentConsumable;

    public string Name
    {
        get{return _name;}
        private set
        {
            _name = value;
            OnPropertyChanged();
        }
    }

    public int CurrentHitPoints
    {
        get{return _currentHitPoints;}
        private set
        {
            _currentHitPoints = value;
            OnPropertyChanged();
        }
    }

    public int MaximumHitPoints
    {
        get{return _maximumHitPoints;}
        protected set
        {
            _maximumHitPoints = value;
            OnPropertyChanged();
        }
    }

    public int Gold
    {
        get{return _gold;}
        private set
        {
            _gold = value;
            OnPropertyChanged();
        }
    }

    public int Level
    {
        get{return _level;}
        protected set
        {
            _level = value;
            OnPropertyChanged();
        }
    }

    public GameItem CurrentWeapon
    {
        get{return _currentWeapon;}
        set
        {
            if(_currentWeapon != null)
            {
                _currentWeapon.Action.OnActionPerformed -= RaiseActionPerformedEvent;
            }
            _currentWeapon = value;
            if(_currentWeapon != null)
            {
                _currentWeapon.Action.OnActionPerformed += RaiseActionPerformedEvent;
            }
            OnPropertyChanged();
        }
    }

    public GameItem CurrentConsumable
    {
        get{return _currentConsumable;}
        set
        {
            if(_currentConsumable != null)
            {
                _currentConsumable.Action.OnActionPerformed -= RaiseActionPerformedEvent;
            }
            _currentConsumable = value;
            if(_currentConsumable != null)
            {
                _currentConsumable.Action.OnActionPerformed += RaiseActionPerformedEvent;
            }
            OnPropertyChanged();
        }
    }
    public ObservableCollection<GameItem> Inventory{get; }
    public ObservableCollection<GroupedInventoryItem> GroupedInventory{get; }
    public List<GameItem> Weapons => Inventory.Where(i => i.Category == GameItem.ItemCategory.Weapon).ToList();
    public List<GameItem> Consumables => Inventory.Where(i => i.Category == GameItem.ItemCategory.Consumable).ToList();
    public bool HasConsumables => Consumables.Any();
    public bool isDead => CurrentHitPoints <= 0;
    public event EventHandler<string> OnActionPerformed;
    public event EventHandler OnKilled;

    protected LivingEntity(string name, int maximumHitPoints, int currentHitPoints, int gold, int level = 1)
    {
        Name = name;
        MaximumHitPoints = maximumHitPoints;
        CurrentHitPoints = currentHitPoints;
        Gold = gold;
        Level = level;

        Inventory = new ObservableCollection<GameItem>();
        GroupedInventory = new ObservableCollection<GroupedInventoryItem>();
    }

    public void UseCurrentWeaponOn(LivingEntity target)
    {
        CurrentWeapon.PerformAction(this, target);
    }

    public void UseCurrentConsumable()
    {
        CurrentConsumable.PerformAction(this, this);
        RemoveItemFromInventory(CurrentConsumable);
    }

    public void TakeDamage(int value)
    {
        CurrentHitPoints -= value;
        if (isDead)
        {
            CurrentHitPoints = 0;
            RaiseOnKilledEvent();
        }
    }

    public void Heal(int value)
    {
        CurrentHitPoints += value;
        if(CurrentHitPoints > MaximumHitPoints)
        {
            CurrentHitPoints = MaximumHitPoints;
        }
    }

    public void CompleteHeal()
    {
        CurrentHitPoints = MaximumHitPoints;
    }

    public void ReceiveGold(int value)
    {
        Gold += value;
    }

    public void SpendGold(int value)
    {
        if(value > Gold)
        {
            throw new ArgumentOutOfRangeException($"{Name} only has {Gold} gold");
        }
        Gold -= value;
    }

    public void AddItemToInventory(GameItem item)
    {   
        Inventory.Add(item);
        if(item.IsUnique){
            GroupedInventory.Add(new GroupedInventoryItem(item, 1));
        }
        else
        {
            if(!GroupedInventory.Any(gi => gi.Item.ItemTypeId == item.ItemTypeId))
            {
                GroupedInventory.Add(new GroupedInventoryItem(item, 0));
            }
            GroupedInventory.First(gi => gi.Item.ItemTypeId == item.ItemTypeId).Quantity++;
        }
        OnPropertyChanged(nameof(Weapons));
        OnPropertyChanged(nameof(Consumables));
        OnPropertyChanged(nameof(HasConsumables));
    }

    public void RemoveItemFromInventory(GameItem item)
    {   
        Inventory.Remove(item);
        GroupedInventoryItem removeItem = item.IsUnique ? 
            GroupedInventory.FirstOrDefault(gi => gi.Item == item) : 
            GroupedInventory.FirstOrDefault(gi => gi.Item.ItemTypeId == item.ItemTypeId);
        if(removeItem != null){
            if(removeItem.Quantity == 1)
            {
                GroupedInventory.Remove(removeItem);
            }
            else
            {
                removeItem.Quantity--;
            }
            OnPropertyChanged(nameof(Weapons));
            OnPropertyChanged(nameof(Consumables));
            OnPropertyChanged(nameof(HasConsumables));
        }
    }

    public void RemoveItemsFromInventory(List<ItemQuantity> itemQuantitys)
    {
        foreach(ItemQuantity itemQuantity in itemQuantitys)
        {
            for(int i = 0; i < itemQuantity.Quantity; i++)
            {
                RemoveItemFromInventory(Inventory.First(item => item.ItemTypeId == itemQuantity.ItemID));
            }
        }
    }

    public bool HasAllTheseItems(List<ItemQuantity> items)
    {
        foreach(ItemQuantity item in items)
        {
            if(Inventory.Count(i => i.ItemTypeId == item.ItemID) < item.Quantity)
            {
                return false;
            }
        }

        return true;
    }


    private void RaiseOnKilledEvent()
    {
        OnKilled?.Invoke(this, new System.EventArgs());
    }

    private void RaiseActionPerformedEvent(object sender,string result)
    {
        OnActionPerformed?.Invoke(this, result);
    }
}

