using WPFUI.Models;

namespace WPFUI.Factories;

public static class TraderFactory
{
    private static List<Trader> _traders = new List<Trader>();

    static TraderFactory()
    {
        Trader susan = new Trader("Susan");
        susan.AddItemToInventory(ItemFactory.CreateGameItem(1001));

        Trader farmerFred = new Trader("Farmer Fred");
        farmerFred.AddItemToInventory(ItemFactory.CreateGameItem(1001));

        Trader pete = new Trader("Pete");
        pete.AddItemToInventory(ItemFactory.CreateGameItem(1001));

        AddTraderToList(susan);
        AddTraderToList(farmerFred);
        AddTraderToList(pete);
    }

    public static Trader GetTraderByName(string name)
    {
        return _traders.FirstOrDefault(t => t.Name == name);
    }

    private static void AddTraderToList(Trader trader)
    {
        if(_traders.Any(t => t.Name == trader.Name))
        {
            throw new ArgumentException($"Already a trader name {trader.Name}");
        }
        _traders.Add(trader);
    }

}

