    {
        /// <summary>
        /// A uniformly distributed random number in [minimumValue, maximumValue], inclusive.
        /// </summary>
        public static int NumberBetween(int minimumValue, int maximumValue)
        {
            if (maximumValue < minimumValue)
            {
                throw new ArgumentException($"{nameof(maximumValue)} must be >= {nameof(minimumValue)}");
            }
            // Fully qualified: this class shadows the framework type of the same name.
            return System.Security.Cryptography.RandomNumberGenerator.GetInt32(minimumValue, maximumValue + 1);
        }
    }
}

