using System;
using System.Security.Cryptography;

namespace WPFUI
{
    // This is the more complex version
    public static class RandomNumberGenerator
    {
        private static readonly RNGCryptoServiceProvider _generator = new RNGCryptoServiceProvider();

        public static int NumberBetween(int minimumValue, int maximumValue)
        {
            byte[] randomNumber = new byte[1];

            _generator.GetBytes(randomNumber);

            double asciiValueOfRandomCharacter = Convert.ToDouble(randomNumber[0]);

            double multiplier = Math.Max(0, (asciiValueOfRandomCharacter / 255d) - 0.00000000001d);

            int range = maximumValue - minimumValue + 1;

            double randomValueInRange = Math.Floor(multiplier * range);

            return (int)(minimumValue + randomValueInRange);
        }

        private static readonly Random _simpleGenerator = new Random();

        public static int SimpleNumberBetween(int minimumValue, int maximumValue)
        {
            return _simpleGenerator.Next(minimumValue, maximumValue + 1);
        }
    }
}

using System.Windows;
using System.Windows.Documents;
using WPFUI.ViewModels; 
using WPFUI.EventArgs;
using WPFUI.Models;

namespace WPFUI;

public partial class MainWindow : Window
{   
    private readonly GameSession _gameSession;

    public MainWindow()
    {
        InitializeComponent();
        _gameSession = new GameSession(
        new Models.Player("Jakob", "Warrior", currentHitPoints: 100, health: 100, experience: 0, gold: 1000000));
        _gameSession.OnMessageRaised += OnGameMessageRaised;
        DataContext = _gameSession;
    }

    private void OnClick_MoveNorth(object sender, RoutedEventArgs e)
    {
        _gameSession.MoveNorth();
    }

    private void OnClick_MoveWest(object sender, RoutedEventArgs e)
    {
        _gameSession.MoveWest();
    }

    private void OnClick_MoveEast(object sender, RoutedEventArgs e)
    {
        _gameSession.MoveEast();
    }

    private void OnClick_MoveSouth(object sender, RoutedEventArgs e)
    {
        _gameSession.MoveSouth();
    }

    private void OnGameMessageRaised(object sender, GameMessageEventArgs e)
    {
        GameMessages.Document.Blocks.Add(new Paragraph(new Run(e.Message)));
        GameMessages.ScrollToEnd();
    }

    private void OnClick_AttackMonster(object sender, RoutedEventArgs e)
    {
        _gameSession.AttackCurrentMonster();
    }

    private void OnClick_DisplayTradeScreen(object sender, RoutedEventArgs e)
    {
        TradeWindow tradeScreen = new TradeWindow();
        tradeScreen.Owner = this;
        tradeScreen.DataContext = _gameSession;
        tradeScreen.ShowDialog();
    }

    private void OnClick_ConsumeItem(object sender, RoutedEventArgs e)
    {
        _gameSession.UseCurrentConsumables();
    }

    private void OnClick_CraftItem(object sender, RoutedEventArgs e)
    {
        Recipe recipe = ((FrameworkElement)sender).DataContext as Recipe;
        _gameSession.CraftItemUsing(recipe);
    }
}

